def transform(grid):
    H, W = len(grid), len(grid[0])
    from collections import Counter
    sep_col = None
    sep_row = None
    for c in range(W):
        if all(grid[r][c] == grid[0][c] for r in range(H)):
            sep_col = c
            break
    if sep_col is None:
        for r in range(H):
            if all(grid[r][c] == grid[r][0] for c in range(W)):
                sep_row = r
                break
    if sep_col is not None:
        L = [row[:sep_col] for row in grid]
        R = [row[sep_col+1:] for row in grid]
    else:
        L = [grid[r] for r in range(sep_row)]
        R = [grid[r] for r in range(sep_row+1, H)]
    cnt = Counter(v for row in R for v in row)
    rmin = min(cnt, key=lambda k: cnt[k])
    h, w = len(L), len(L[0])
    return [[3 if L[r][c] == R[r][c] else rmin for c in range(w)] for r in range(h)]
